from rules import resolve


def solve(data):
    versions = resolve(data)
    if versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": versions}

def _matches(version, bounds):
    return all(
        (minimum is None or minimum <= version)
        and (maximum is None or version <= maximum)
        for minimum, maximum in bounds
    )


def _dependency(dependency):
    if isinstance(dependency, str):
        return dependency, (None, None)
    if isinstance(dependency, dict) and "name" in dependency:
        return dependency["name"], (
            dependency.get("min"),
            dependency.get("max"),
        )
    return None


def _has_cycle(graph):
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return True
        if name in visited:
            return False
        visiting.add(name)
        for dependency in graph.get(name, ()):
            if visit(dependency):
                return True
        visiting.remove(name)
        visited.add(name)
        return False

    return any(visit(name) for name in graph if name not in visited)


def resolve(data):
    packages = data["packages"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)
    constraints = {
        name: [tuple(bounds)] for name, bounds in data["roots"].items()
    }
    best_vector = None
    best_versions = None

    def search(assigned, current_constraints, graph):
        nonlocal best_vector, best_versions

        pending = set(current_constraints).difference(assigned)
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = min(pending)
        forbidden = blocked.get(name, ())
        for row in packages.get(name, []):
            version = row["version"]
            if version in forbidden or (name in pins and version != pins[name]):
                continue
            if not _matches(version, current_constraints[name]):
                continue

            active_dependencies = []
            parsed_dependencies = []
            valid = True
            for raw_dependency in row.get("deps", []):
                if isinstance(raw_dependency, dict):
                    feature = raw_dependency.get("feature")
                    if feature and feature not in features:
                        continue

                parsed = _dependency(raw_dependency)
                if parsed is None:
                    valid = False
                    break
                dep_name, bounds = parsed
                active_dependencies.append(dep_name)
                parsed_dependencies.append((dep_name, bounds))

            if not valid:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = {
                package: list(ranges)
                for package, ranges in current_constraints.items()
            }
            for dep_name, bounds in parsed_dependencies:
                next_constraints.setdefault(dep_name, []).append(bounds)
                if dep_name in next_assigned and not _matches(
                    next_assigned[dep_name], next_constraints[dep_name]
                ):
                    valid = False
                    break
            if not valid:
                continue

            next_graph = {package: list(edges) for package, edges in graph.items()}
            next_graph[name] = active_dependencies
            if not _has_cycle(next_graph):
                search(next_assigned, next_constraints, next_graph)

    search({}, constraints, {})
    return best_versions
